# 15. Distribution classification by skewness threshold
for col in ['revenue', 'units_sold', 'discount_pct', 'revenue_outlier_flag']:
    skew = df[col].skew()
    kurt = df[col].kurt()
    if abs(skew) < 0.5:
        dist_type = 'normal'
    elif skew > 0.5:
        dist_type = 'skewed_right'
    else:
        dist_type = 'skewed_left'
    print(f'{col}: {dist_type}, skewness={skew:.3f}, kurtosis={kurt:.3f}')
